-- Catálogo de cámaras, Tanda 1: Canon (Diego, 20-nov: «Sí a todo»).
--
-- 253 modelos de film del Canon Camera Museum: solo datos sueltos (nombre,
-- año de venta, tipo, formato y montura), con la URL de cada ficha como
-- fuente. Cada nombre regional es su propio modelo; las variantes con
-- fechador (QD, Date, Caption) son una. Lo que ninguna fuente confirma queda
-- vacío. Revisión: docs privados, TANDA-1-CANON. Por clave: nunca duplica ni
-- pisa lo corregido desde el panel.

insert into public.camera_models
  (manufacturer_id, name, type, format, mount_id, interchangeable, year_from,
   source, source_ref, status)
select app_private.manufacturer_for('Canon', null, true), v.name, v.type, v.format,
       (select m.id from public.lens_mounts m where m.status = 'approved' and m.name = v.mount),
       v.interchangeable, v.year, 'canon', v.ref, 'approved'
